import { StudioProApi } from "@mendix/extensions-api";
import { createStudioProLogger } from "../config/logger";
import { Model, ModelType, Provider } from "../types/model/model";
import { MxCloudGenAIModelFields } from "../types/model/mxCloudGenAIModel";

export const updateModelDocument = (studioPro: StudioProApi, documentId: string) => async (model: Model) => {
    const logger = createStudioProLogger(studioPro);
    try {
        await studioPro.app.model.customBlobDocuments.updateDocumentContent(documentId, model);
    } catch (error) {
        logger.error("Failed to save model document:", error);
        await studioPro.ui.notifications.show({
            title: "Failed to save model document.",
            message: (error as Error).message,
        });
    }
};

export function createNewModel(): Model {
    return {
        type: "" as ModelType,
        name: "",
        displayName: "",
        provider: "MxCloudGenAI" as Provider, // Preselect MxCloudGenAI as default provider
        providerFields: createNewMxCloudGenAIModelFields(),
    };
}

export const createNewMxCloudGenAIModelFields = (): MxCloudGenAIModelFields => {
    return {
        environment: "",
        deepLinkURL: "",
        key: "",
        keyId: "",
        keyName: "",
        resourceName: "",
    };
};

/**
 * Clears the model details while preserving provider-specific fields that are necessary for maintaining the connection to the provider.
 * @param model - The model to clear.
 * @returns The cleared model.
 */
export const clearModelDetails = (model: Model): Model => {
    const providerFields = model.providerFields as MxCloudGenAIModelFields;

    const clearedModel = {
        ...createNewModel(),
        type: model.type,
        provider: model.provider,
        providerFields: {
            ...createNewMxCloudGenAIModelFields(),
            key: providerFields.key,
        },
    };

    return clearedModel;
};
